        margin-top: 28px;
      }

      .feature-item {
        padding: 18px 20px;
        border-radius: 20px;
        background: rgba(255, 255, 255, 0.8);
        border: 1px solid rgba(148, 163, 184, 0.18);
      }

      .feature-item strong {
        display: block;
        margin-bottom: 6px;
        font-size: 0.98rem;
      }

      .feature-item span {
        color: var(--muted);
        line-height: 1.55;
        font-size: 0.95rem;
      }

      .form-panel {
        padding: 32px;
      }

      .form-panel h2 {
        margin: 0 0 8px;
        font-size: 1.7rem;
      }

      .form-panel p {
        margin: 0 0 24px;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 700;
        font-size: 0.95rem;
      }

      input {
        width: 100%;
        border: 1px solid var(--input-border);
        border-radius: 16px;
        padding: 14px 16px;
        font: inherit;
        color: var(--text);
        background: #fff;
        transition: border-color 140ms ease, box-shadow 140ms ease, background-color 140ms ease;
      }

      input::placeholder {
        color: #94a3b8;
      }

      input:focus {
        outline: none;
        border-color: var(--primary);
        box-shadow: 0 0 0 4px var(--input-focus);
      }

      .field-help {
        margin: 0;
        color: var(--muted);
        font-size: 0.88rem;
      }

      .field-error {
        margin: 0;
        min-height: 1.1rem;
        color: var(--danger);
        font-size: 0.88rem;
      }

      .input-error {
        border-color: var(--danger);
        background: var(--danger-soft);
      }

      .submit-button {
        margin-top: 8px;
        border: 0;
        border-radius: 16px;
        padding: 15px 18px;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--primary), var(--primary-dark));
        cursor: pointer;
        transition: transform 140ms ease, box-shadow 140ms ease, opacity 140ms ease;
        box-shadow: 0 16px 32px rgba(37, 99, 235, 0.24);
      }

      .submit-button:hover {
        transform: translateY(-1px);
      }

      .submit-button:active {
        transform: translateY(0);
      }

      .status-banner {
        border-radius: 18px;
        padding: 14px 16px;
        font-size: 0.95rem;
        line-height: 1.5;
      }

      .status-success {
        color: #166534;
        background: rgba(34, 197, 94, 0.12);
        border: 1px solid rgba(34, 197, 94, 0.22);
      }

      @media (max-width: 860px) {
        .page-shell {
          grid-template-columns: 1fr;
        }

        .hero-panel,
        .form-panel {
          padding: 28px;
        }
      }
    </style>
  </head>
  <body>
    <div id="app"></div>

    <script>
      const initialState = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        errors: {},
        submitted: false,
      };

      let state = { ...initialState, values: { ...initialState.values }, errors: {} };

      const phoneHint = "Optional. Use digits only or include separators like (555) 123-4567.";

      const fieldConfig = [
        {
          id: "fullName",
          label: "Full name",
          type: "text",
          placeholder: "Taylor Morgan",
          required: true,
        },
        {
          id: "email",
          label: "Email address",
          type: "email",
          placeholder: "taylor@example.com",
          required: true,
        },
        {
          id: "phone",
          label: "Phone number",
          type: "tel",
          placeholder: "(555) 123-4567",
          required: false,
          helperText: phoneHint,
        },
      ];

      function validate(values) {
        const errors = {};
        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        const phonePattern = /^[+]?[0-9()\-\s]{7,20}$/;

        if (!values.fullName.trim()) {
          errors.fullName = "Enter your full name.";
        }

        if (!values.email.trim()) {
          errors.email = "Enter your email address.";
        } else if (!emailPattern.test(values.email.trim())) {
          errors.email = "Enter a valid email address.";
        }

        if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
          errors.phone = "Use a valid phone format such as (555) 123-4567.";
        }

        return errors;
      }

      function FormField(field) {
        const value = state.values[field.id];
        const error = state.errors[field.id];
        const errorId = field.id + "-error";
        const helpId = field.id + "-help";
        const describedBy = [field.helperText ? helpId : "", error ? errorId : ""]
          .filter(Boolean)
          .join(" ");

        return `
          <div class="form-field">
            <label for="${field.id}">${field.label}${field.required ? " *" : ""}</label>
            <input
              id="${field.id}"
              name="${field.id}"
              type="${field.type}"
              placeholder="${field.placeholder}"
              value="${escapeHtml(value)}"
              ${error ? 'class="input-error"' : ""}
              aria-invalid="${error ? "true" : "false"}"
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            />
            ${
              field.helperText
                ? `<p class="field-help" id="${helpId}">${field.helperText}</p>`
                : ""
            }
            <p class="field-error" id="${errorId}">${error || ""}</p>
          </div>
        `;
      }

      function HeroPanel() {
        return `
          <section class="hero-panel">
            <div>
              <div class="eyebrow">Support team online</div>
              <h1>Get help from product specialists.</h1>
              <p class="hero-copy">
                Share a few details and our support team will follow up with the right guidance for your
                account, setup, or billing questions.
              </p>
            </div>
            <div class="feature-list">
              <div class="feature-item">
                <strong>Fast routing</strong>
                <span>Your request goes straight to the team best equipped to help.</span>
              </div>
              <div class="feature-item">
                <strong>Clear updates</strong>
                <span>We use your contact details to confirm next steps and keep the conversation moving.</span>
              </div>
            </div>
          </section>
        `;
      }

      function SupportForm() {
        const successMessage = state.submitted
          ? '<div class="status-banner status-success">Thanks — your support request is ready to send.</div>'
          : "";

        return `
          <section class="form-panel">
            <h2>Contact support</h2>
            <p>Required fields are marked with an asterisk.</p>
            <form id="support-form" novalidate>
              ${fieldConfig.map(FormField).join("")}
              <button class="submit-button" type="submit">Submit request</button>
            </form>
            ${successMessage}
          </section>
        `;
      }

      function App() {
        return `
          <main class="page-shell">
            ${HeroPanel()}
            ${SupportForm()}
          </main>
        `;
      }

      function escapeHtml(value) {
        return value
          .replaceAll("&", "&amp;")
          .replaceAll('"', "&quot;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;");
      }

      function render() {
        document.getElementById("app").innerHTML = App();
        const form = document.getElementById("support-form");

        for (const field of fieldConfig) {
          const input = document.getElementById(field.id);
          input.addEventListener("input", handleInput);
          input.addEventListener("blur", handleBlur);
        }

        form.addEventListener("submit", handleSubmit);
      }

      function handleInput(event) {
        const { name, value } = event.target;
        state = {
          ...state,
          submitted: false,
          values: { ...state.values, [name]: value },
        };

        const nextErrors = validate(state.values);
        state = { ...state, errors: nextErrors };
        render();

        const input = document.getElementById(name);
        input.focus();
        input.setSelectionRange(value.length, value.length);
      }

      function handleBlur() {
        state = { ...state, errors: validate(state.values) };
        render();
      }

      function handleSubmit(event) {
        event.preventDefault();
        const nextErrors = validate(state.values);

        if (Object.keys(nextErrors).length > 0) {
          state = { ...state, errors: nextErrors, submitted: false };
          render();
          return;
        }

        state = { ...state, errors: {}, submitted: true };
        render();
      }

      render();
    </script>
  </body>
</html>
